<script setup lang="ts">
import { useGovPage } from '../../useGovPage'
useGovPage()
import AuthorizationNotice from '../../components/AuthorizationNotice.vue'
import { computed,ref } from 'vue'
import { onShow,onPullDownRefresh } from '@dcloudio/uni-app'
import { api,statusMeta,type Task } from '../../api'
const items=ref<Task[]>([]),tab=ref('all'),loading=ref(false),error=ref(''),keyword=ref('')
const visible=computed(()=>items.value.filter(i=>(tab.value==='all'||i.status===tab.value)&&`${i.subjectName} ${i.taskNo}`.toLowerCase().includes(keyword.value.trim().toLowerCase())))
onShow(load)
onPullDownRefresh(load)
async function load(){if(loading.value){uni.stopPullDownRefresh();return}loading.value=true;error.value='';try{items.value=await api.tasks()}catch(e){items.value=[];error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function open(id:number){uni.navigateTo({url:`/pages/tasks/detail?id=${id}`})}
</script>
<template><view class="page pad"><AuthorizationNotice duty="inspection" context="tasks"/><view class="between"><view><text class="page-title">执法任务</text><text class="tiny">本人承办任务 · 下拉刷新</text></view><text class="tag orange">{{items.filter(i=>i.status!=='completed').length}} 项待办</text></view><input class="input list-search" v-model="keyword" placeholder="搜索主体名称或任务编号" confirm-type="search"/><scroll-view scroll-x class="filter-scroll" :show-scrollbar="false"><view class="tabs"><button v-for="t in [['all','全部'],['pending','待检查'],['in_progress','进行中'],['completed','已完成']]" :key="t[0]" :class="{on:tab===t[0]}" @tap="tab=t[0]">{{t[1]}}</button></view></scroll-view><view v-if="loading" class="loading">正在加载任务…</view><view v-else-if="error" class="state-panel"><text>{{error}}</text><button class="btn" @tap="load">重新加载</button></view><view v-else-if="!visible.length" class="empty"><text class="empty-icon">📋</text><text>当前没有任务</text></view><view v-else class="task-list"><view class="task" v-for="item in visible" :key="item.id" @tap="open(item.id)"><view class="between"><view><text class="strong">{{item.subjectName}}</text><text class="tiny">{{item.taskNo}} · {{item.taskType}}</text></view><text class="tag" :class="statusMeta(item.status).tone">{{statusMeta(item.status).label}}</text></view><text class="muted">📍 {{item.address}}</text><progress class="progress" :percent="item.checklistTotal?Math.min(100,Math.max(0,item.checklistDone/item.checklistTotal*100)):0" activeColor="#12764a" backgroundColor="#e7eee9" :stroke-width="4" /><view class="between"><text class="tiny">检查项 {{item.checklistDone}}/{{item.checklistTotal}} · {{item.deadline}}</text><text class="link">{{item.status==='pending'?'开始检查':'查看详情'}} ›</text></view></view></view></view></template>
<style lang="scss" scoped>.page-title{display:block;font-size:38rpx;font-weight:750}.filter-scroll{width:100%;white-space:nowrap}.tabs{display:inline-flex;gap:8rpx;margin:18rpx 0}.tabs button{padding:11rpx 20rpx;border-radius:24rpx;background:#e9f0ec;color:#666666;font-size:24rpx}.tabs button.on{background:#12764a;color:#fff}.task{margin-bottom:14rpx;padding:20rpx;border:1rpx solid #e1e9e3;border-radius:20rpx;background:#fff}.task>view:nth-of-type(1)>view{display:flex;flex-direction:column;gap:4rpx}.task>.muted{display:block;margin:9rpx 0}.task .progress{margin:12rpx 0 8rpx}.link{color:#12764a;font-size:24rpx}.list-search{margin-top:24rpx}.tabs button{min-height:88rpx}.task{padding:26rpx}.task .strong{font-size:30rpx}</style>
